/// <summary>
/// Import a document link for a record without prior export.
/// </summary>
[System.ComponentModel.Composition.ExportMetadataAttribute(enumStr(AVADAIAcknowledgementImportType), AVADAIAcknowledgementImportType::AdHocDocType),
    System.ComponentModel.Composition.ExportAttribute('Dynamics.AX.Application.AVADAIImportSerializer')]
class AVADAIImportAdhocDoctype extends AVADAIImportAckSerializer
{
    TableName       tableName;
    FieldName       fieldName;
    DataAreaId      company;
    AVADAIRefNum    refNum;


}

Method.Source:
/// <summary>
/// Initialization table with ack.
/// </summary>
/// <param name = "_acknowledgement">The sAVADAIAcknowledgementImport.</param>
public void initAcknowledgment(AVADAIAcknowledgementImport _acknowledgement)
{
    AVADAIAdhocDoctypes     AVADAIAdhocDoctypes;

    AVADAIAdhocDoctypes = AVADAIAdhocDoctypes::find(_acknowledgement.DocuTypeId);
    if(AVADAIAdhocDoctypes)
    {
        //change the type to a real type
        _acknowledgement.DocuTypeId         = AVADAIAdhocDoctypes.DoctypeId; 

        if(!_acknowledgement.TableName)
        {
            _acknowledgement.TableName      = AVADAIAdhocDoctypes.TableNameFixed;
        }
        if(!_acknowledgement.TableFieldName)
        {
            _acknowledgement.TableFieldName = AVADAIAdhocDoctypes.FieldNameFixed;
        }
        if(!_acknowledgement.Company)
        {
            _acknowledgement.Company        = AVADAIAdhocDoctypes.CompanyFixed;
        }

        if(!_acknowledgement.DocuRefName)
        {
            _acknowledgement.DocuRefName     = DocuType::find(_acknowledgement.DocuTypeId).Name;
        }

    }
}

/// <summary>
/// Always return empty record.
/// </summary>
/// <param name = "_serverId">DMS server id</param>
/// <param name = "_ackFileName">imported file</param>
/// <returns>Empty record</returns>
protected AVADAIReportExportTable findExportMetadata(AVADAIServerId _serverId, AVADAIFileNameAck _ackFileName)
{
    AVADAIReportExportTable ret;

    return ret;
}
